func half(value) { return value / 2.0 }
mut i := 0
while i < 200 { assert_equal(half(7), 3.5) i += 1 }
print("PASS")

mut rng := 42
func random_int(maximum) {
    rng = (rng * 3877 + 29573) % 139968
    return to_int(to_float(rng) / 139968.0 * maximum)
}
mut total := 0
mut i := 0
while i < 1000 { total += random_int(1000000) i += 1 }
print(total)

mut count := 0
func bump() { count = count + 1 return count }
mut i := 0
while i < 200 { i += 1 assert_equal(bump(), i) }
assert_equal(count, 200)
print("PASS")

func yes() { return true }
mut i := 0
while i < 200 { assert_equal(yes(), true) i += 1 }
print("PASS")
